for s, p in deps:
    pred[s].append(p)
    succ[p].append(s)

in_degree = {t: len(pred[t]) for t in durations}
queue = [t for t in durations if in_degree[t] == 0]
eset = {t: 0 for t in durations}
while queue:
    u = queue.pop(0)
    for v in succ[u]:
        if eset[u] + durations[u] > eset[v]:
            eset[v] = eset[u] + durations[u]
        in_degree[v] -= 1
        if in_degree[v] == 0:
            queue.append(v)

result = max(eset[t] + durations[t] for t in durations)

